import { getDb } from "./db";
import { getSplits, splitFactorLookup } from "./prices";
import type { SeriesPoint } from "./types";

/**
 * "What if every dividend had bought the index instead?"
 *
 * A portfolio of hand-entered positions, run forward through the stored price,
 * dividend and split history, in three parallel worlds:
 *
 *   1. dividends buy SPY               — the counterfactual being asked about
 *   2. dividends pile up as cash       — the honest baseline to judge it against
 *   3. dividends vanish                — just the shares, for reference
 *
 * All three hold exactly the same shares of the original companies; they differ
 * only in what happens to the cash the companies pay out. Nothing is ever sold.
 */

export const SPY_TICKER = "SPY";

/** Fractional shares trade in hundredths, so that is the lot the sim buys in. */
export const SPY_LOT = 0.01;

/** US withholding on dividends paid to a Czech resident with a W-8BEN on file. */
export const WITHHOLDING_TAX = 0.15;

/**
 * How long a dividend may wait for a usable SPY close before the sim gives up
 * and leaves it in cash. Weekly bars mean a few days of slack is normal; a gap
 * larger than this means the dividend fell outside the stored SPY history.
 */
const SETTLE_WINDOW_DAYS = 31;

/* ------------------------------------------------------------------ */
/* positions                                                           */
/* ------------------------------------------------------------------ */

export type Position = {
  id: number;
  ticker: string;
  shares: number;
  buyDate: string;
  /** Null means the sim uses the close of the buy date as the cost basis. */
  buyPrice: number | null;
  note: string | null;
};

export type PositionInput = {
  ticker: string;
  shares: number;
  buyDate: string;
  buyPrice?: number | null;
  note?: string | null;
};

type PositionRow = {
  id: number;
  ticker: string;
  shares: number;
  buy_date: string;
  buy_price: number | null;
  note: string | null;
};

const toPosition = (r: PositionRow): Position => ({
  id: r.id,
  ticker: r.ticker,
  shares: r.shares,
  buyDate: r.buy_date,
  buyPrice: r.buy_price,
  note: r.note,
});

export function listPositions(): Position[] {
  const rows = getDb()
    .prepare(
      `SELECT id, ticker, shares, buy_date, buy_price, note
       FROM positions ORDER BY buy_date, ticker, id`,
    )
    .all() as PositionRow[];
  return rows.map(toPosition);
}

export function getPosition(id: number): Position | null {
  const row = getDb()
    .prepare(
      `SELECT id, ticker, shares, buy_date, buy_price, note FROM positions WHERE id = ?`,
    )
    .get(id) as PositionRow | undefined;
  return row ? toPosition(row) : null;
}

export function addPosition(input: PositionInput): Position {
  const info = getDb()
    .prepare(
      `INSERT INTO positions (ticker, shares, buy_date, buy_price, note, created_at)
       VALUES (?,?,?,?,?,?)`,
    )
    .run(
      input.ticker,
      input.shares,
      input.buyDate,
      input.buyPrice ?? null,
      input.note ?? null,
      new Date().toISOString(),
    );
  return getPosition(Number(info.lastInsertRowid))!;
}

export function updatePosition(id: number, input: PositionInput): Position | null {
  const info = getDb()
    .prepare(
      `UPDATE positions SET ticker = ?, shares = ?, buy_date = ?, buy_price = ?, note = ?
       WHERE id = ?`,
    )
    .run(
      input.ticker,
      input.shares,
      input.buyDate,
      input.buyPrice ?? null,
      input.note ?? null,
      id,
    );
  return info.changes ? getPosition(id) : null;
}

export function deletePosition(id: number): boolean {
  return getDb().prepare(`DELETE FROM positions WHERE id = ?`).run(id).changes > 0;
}

/* ------------------------------------------------------------------ */
/* price / dividend lookups                                            */
/* ------------------------------------------------------------------ */

export type Bar = { date: string; close: number };

export function loadBars(ticker: string): Bar[] {
  return getDb()
    .prepare(
      `SELECT date, close FROM prices
       WHERE ticker = ? AND close IS NOT NULL ORDER BY date`,
    )
    .all(ticker) as Bar[];
}

export function loadDividends(ticker: string): { date: string; amount: number }[] {
  return getDb()
    .prepare(`SELECT date, amount FROM dividends WHERE ticker = ? ORDER BY date`)
    .all(ticker) as { date: string; amount: number }[];
}

/** Last bar on or before `date` — the price a holder could mark to that day. */
export function barAsOf(bars: Bar[], date: string): Bar | null {
  let lo = 0;
  let hi = bars.length - 1;
  let hit = -1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (bars[mid].date <= date) {
      hit = mid;
      lo = mid + 1;
    } else hi = mid - 1;
  }
  return hit === -1 ? null : bars[hit];
}

/** First bar on or after `date` — the earliest close a buyer could actually get. */
export function barAtOrAfter(bars: Bar[], date: string): Bar | null {
  let lo = 0;
  let hi = bars.length - 1;
  let hit = -1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (bars[mid].date >= date) {
      hit = mid;
      hi = mid - 1;
    } else lo = mid + 1;
  }
  return hit === -1 ? null : bars[hit];
}

const dayGap = (from: string, to: string) =>
  Math.round((Date.parse(to) - Date.parse(from)) / 86_400_000);

/* ------------------------------------------------------------------ */
/* simulation                                                          */
/* ------------------------------------------------------------------ */

/** One dividend payment and what the sim did with it. */
export type DividendEvent = {
  positionId: number;
  ticker: string;
  /** Date the dividend was paid, as the feed reports it. */
  date: string;
  /** Date the money was actually put to work — the first usable SPY close. */
  settleDate: string;
  perShare: number;
  shares: number;
  gross: number;
  tax: number;
  net: number;
  /** Null when no SPY close was available close enough to invest at. */
  spyPrice: number | null;
  /** Fractional SPY bought here — always a whole number of 0.01 lots. */
  spyBought: number;
  /** Running totals after this event, so the table shows the state, not just the delta. */
  spySharesAfter: number;
  cashAfter: number;
};

export type PositionResult = {
  id: number;
  ticker: string;
  /** Shares as entered, on the basis of the buy date. */
  shares: number;
  /** Shares today, after every split since the buy date. */
  sharesNow: number;
  buyDate: string;
  buyPrice: number | null;
  cost: number | null;
  value: number | null;
  lastPrice: number | null;
  dividendsNet: number;
  splitFactor: number;
  /** Why this position contributes nothing, when it does not. */
  problem: string | null;
};

export type PortfolioSummary = {
  firstDate: string | null;
  lastDate: string | null;
  years: number;
  /** What was paid for the shares. */
  invested: number;
  /** Today's value of the shares themselves. */
  stocksValue: number;
  dividendsGross: number;
  dividendsTax: number;
  dividendsNet: number;
  spyShares: number;
  spyValue: number;
  spyCost: number;
  /** Average price paid across every SPY purchase. */
  spyAvgPrice: number | null;
  spyLastPrice: number | null;
  /** Dividend money too small to buy a 0.01 lot yet. */
  cash: number;
  /** Shares + SPY + leftover cash. */
  totalReinvested: number;
  /** Shares + every dividend kept as cash. */
  totalCashOnly: number;
  /** Shares alone. */
  totalStocksOnly: number;
  advantage: number;
  advantagePct: number | null;
  /** SPY as a share of the reinvested portfolio, in percent. */
  spyWeight: number | null;
  cagrReinvested: number | null;
  cagrCashOnly: number | null;
};

export type Simulation = {
  taxRate: number;
  timeline: Record<string, SeriesPoint[]>;
  events: DividendEvent[];
  positions: PositionResult[];
  summary: PortfolioSummary;
  warnings: string[];
};

const EMPTY_SUMMARY: PortfolioSummary = {
  firstDate: null,
  lastDate: null,
  years: 0,
  invested: 0,
  stocksValue: 0,
  dividendsGross: 0,
  dividendsTax: 0,
  dividendsNet: 0,
  spyShares: 0,
  spyValue: 0,
  spyCost: 0,
  spyAvgPrice: null,
  spyLastPrice: null,
  cash: 0,
  totalReinvested: 0,
  totalCashOnly: 0,
  totalStocksOnly: 0,
  advantage: 0,
  advantagePct: null,
  spyWeight: null,
  cagrReinvested: null,
  cagrCashOnly: null,
};

/**
 * Run the portfolio forward.
 *
 * Everything is kept on the as-traded basis of each date: a dividend per share
 * reported in 1995 is multiplied by the share count that was actually held in
 * 1995, and a position bought before a 4:1 split holds four times the shares
 * after it. That keeps cash flows and market values on the same footing without
 * ever touching the adjusted close, which already has dividends baked in and
 * would double-count them here.
 */
export function simulate(positions: Position[], taxRate: number): Simulation {
  const warnings: string[] = [];
  if (positions.length === 0) {
    return {
      taxRate,
      timeline: {},
      events: [],
      positions: [],
      summary: EMPTY_SUMMARY,
      warnings,
    };
  }

  const tickers = [...new Set(positions.map((p) => p.ticker))];
  const bars = new Map<string, Bar[]>();
  const factor = new Map<string, (date: string) => number>();
  for (const t of [...tickers, SPY_TICKER]) {
    if (bars.has(t)) continue;
    bars.set(t, loadBars(t));
    factor.set(t, splitFactorLookup(getSplits(t)));
  }

  const spyBars = bars.get(SPY_TICKER)!;
  if (spyBars.length === 0) {
    warnings.push(
      `${SPY_TICKER} nemá v databázi žádné ceny — stáhni ho v záložce „Data a stahování“, jinak není do čeho reinvestovat.`,
    );
  }
  const spyFirst = spyBars[0]?.date ?? null;
  const spyLast = spyBars[spyBars.length - 1] ?? null;

  /* ---- which positions can be valued at all ---- */

  const results: PositionResult[] = [];
  const active: Position[] = [];

  for (const p of positions) {
    const own = bars.get(p.ticker)!;
    const f = factor.get(p.ticker)!;
    // Splits between the buy date and the last known close multiply the shares held.
    const asOfDate = own[own.length - 1]?.date ?? p.buyDate;
    const splitFactor = f(p.buyDate) / f(asOfDate);
    const base: PositionResult = {
      id: p.id,
      ticker: p.ticker,
      shares: p.shares,
      sharesNow: p.shares * splitFactor,
      buyDate: p.buyDate,
      buyPrice: p.buyPrice,
      cost: p.buyPrice !== null ? p.buyPrice * p.shares : null,
      value: null,
      lastPrice: null,
      dividendsNet: 0,
      splitFactor,
      problem: null,
    };

    if (own.length === 0) {
      results.push({ ...base, problem: "žádné stažené ceny" });
      warnings.push(`${p.ticker} nemá stažené ceny — pozice se do výpočtu nezapočítá.`);
      continue;
    }
    if (p.buyDate > own[own.length - 1].date) {
      results.push({ ...base, problem: "datum nákupu je za koncem historie cen" });
      warnings.push(
        `${p.ticker}: ceny končí ${own[own.length - 1].date}, nákup ${p.buyDate} je novější — pozice se nezapočítá, dokud ceny nedoplníš.`,
      );
      continue;
    }
    if (p.buyDate < own[0].date) {
      warnings.push(
        `${p.ticker}: historie cen začíná až ${own[0].date}, nákup ${p.buyDate} se počítá od prvního známého kurzu.`,
      );
    }

    const last = own[own.length - 1];
    // A buy date before the history starts falls back to the first known close.
    const atBuy = barAsOf(own, p.buyDate) ?? own[0];
    results.push({
      ...base,
      cost: (p.buyPrice ?? atBuy.close) * p.shares,
      lastPrice: last.close,
      value: p.shares * splitFactor * last.close,
    });
    active.push(p);
  }

  if (active.length === 0) {
    return {
      taxRate,
      timeline: {},
      events: [],
      positions: results,
      summary: EMPTY_SUMMARY,
      warnings,
    };
  }

  /* ---- collect every dividend the holdings would have received ---- */

  type Pending = Omit<DividendEvent, "spySharesAfter" | "cashAfter">;
  const pending: Pending[] = [];
  let missedBeforeSpy = 0;
  let missedAfterSpy = 0;

  for (const p of active) {
    const f = factor.get(p.ticker)!;
    for (const d of loadDividends(p.ticker)) {
      // Buying on the ex-date is too late to collect that payment.
      if (d.date <= p.buyDate) continue;
      const shares = p.shares * (f(p.buyDate) / f(d.date));
      const gross = shares * d.amount;
      if (!Number.isFinite(gross) || gross <= 0) continue;
      const tax = gross * taxRate;

      const bar = barAtOrAfter(spyBars, d.date);
      const usable = bar && dayGap(d.date, bar.date) <= SETTLE_WINDOW_DAYS ? bar : null;
      if (!usable) {
        if (spyFirst && d.date < spyFirst) missedBeforeSpy++;
        else missedAfterSpy++;
      }

      pending.push({
        positionId: p.id,
        ticker: p.ticker,
        date: d.date,
        // Without a usable close the money simply waits in cash from the pay date.
        settleDate: usable ? usable.date : d.date,
        perShare: d.amount,
        shares,
        gross,
        tax,
        net: gross - tax,
        spyPrice: usable ? usable.close : null,
        spyBought: 0,
      });
    }
  }

  if (missedBeforeSpy > 0 && spyFirst) {
    warnings.push(
      `${missedBeforeSpy} dividend padlo před začátek historie SPY (${spyFirst}) — zůstávají v hotovosti, dokud nepřijde první investovatelný kurz.`,
    );
  }
  if (missedAfterSpy > 0) {
    warnings.push(
      `${missedAfterSpy} dividend nemá do ${SETTLE_WINDOW_DAYS} dnů žádný kurz SPY — zůstávají v hotovosti. Doplň ceny SPY.`,
    );
  }

  // Settled order is what the cash pool actually sees.
  pending.sort((a, b) => a.settleDate.localeCompare(b.settleDate) || a.ticker.localeCompare(b.ticker));

  /* ---- walk the cash pool ---- */

  // Lots are integers so repeated purchases cannot drift off the 0.01 grid.
  let lots = 0;
  let cash = 0;
  let cumulativeNet = 0;
  let spyCost = 0;
  const events: DividendEvent[] = [];
  const dividendsByPosition = new Map<number, number>();

  for (const ev of pending) {
    cash += ev.net;
    cumulativeNet += ev.net;
    dividendsByPosition.set(
      ev.positionId,
      (dividendsByPosition.get(ev.positionId) ?? 0) + ev.net,
    );

    let bought = 0;
    if (ev.spyPrice !== null && ev.spyPrice > 0) {
      // Whole 0.01 lots only; the remainder waits for the next dividend.
      const affordable = Math.floor((cash / ev.spyPrice) * 100 + 1e-9);
      if (affordable > 0) {
        bought = affordable / 100;
        const spend = bought * ev.spyPrice;
        lots += affordable;
        cash -= spend;
        spyCost += spend;
      }
    }

    events.push({
      ...ev,
      spyBought: bought,
      spySharesAfter: lots / 100,
      cashAfter: cash,
    });
  }

  /* ---- value the three worlds on every date we have a price for ---- */

  const start = active.reduce((min, p) => (p.buyDate < min ? p.buyDate : min), active[0].buyDate);
  const grid = new Set<string>([start]);
  for (const p of active) {
    for (const b of bars.get(p.ticker)!) if (b.date >= start) grid.add(b.date);
  }
  for (const b of spyBars) if (b.date >= start) grid.add(b.date);
  const dates = [...grid].sort();

  const reinvested: SeriesPoint[] = [];
  const cashOnly: SeriesPoint[] = [];
  const stocksOnly: SeriesPoint[] = [];
  const advantage: SeriesPoint[] = [];
  const spySharesSeries: SeriesPoint[] = [];

  let cursor = 0;
  let runLots = 0;
  let runCash = 0;
  let runNet = 0;

  for (const date of dates) {
    while (cursor < events.length && events[cursor].settleDate <= date) {
      const ev = events[cursor];
      runNet += ev.net;
      runLots = Math.round(ev.spySharesAfter * 100);
      runCash = ev.cashAfter;
      cursor++;
    }

    let stocks = 0;
    for (const p of active) {
      if (p.buyDate > date) continue;
      const bar = barAsOf(bars.get(p.ticker)!, date);
      if (!bar) continue;
      const f = factor.get(p.ticker)!;
      stocks += p.shares * (f(p.buyDate) / f(date)) * bar.close;
    }

    const spyBar = barAsOf(spyBars, date);
    const spyValue = spyBar ? (runLots / 100) * spyBar.close : 0;
    const withSpy = stocks + spyValue + runCash;
    const withCash = stocks + runNet;

    reinvested.push({ date, value: withSpy });
    cashOnly.push({ date, value: withCash });
    stocksOnly.push({ date, value: stocks });
    advantage.push({ date, value: withSpy - withCash });
    spySharesSeries.push({ date, value: runLots / 100 });
  }

  /* ---- summary ---- */

  for (const r of results) r.dividendsNet = dividendsByPosition.get(r.id) ?? 0;

  const spyShares = lots / 100;
  const spyLastPrice = spyLast?.close ?? null;
  const spyValue = spyLastPrice !== null ? spyShares * spyLastPrice : 0;
  const stocksValue = results.reduce((s, r) => s + (r.value ?? 0), 0);
  // Only positions the sim could actually run; counting the cost of one it had
  // to skip would make every return figure below it wrong.
  const invested = results.reduce((s, r) => s + (r.problem ? 0 : r.cost ?? 0), 0);
  const dividendsGross = events.reduce((s, e) => s + e.gross, 0);
  const dividendsTax = events.reduce((s, e) => s + e.tax, 0);
  const dividendsNet = dividendsGross - dividendsTax;

  const totalReinvested = stocksValue + spyValue + cash;
  const totalCashOnly = stocksValue + dividendsNet;
  const lastDate = dates[dates.length - 1] ?? null;
  const years = lastDate ? dayGap(start, lastDate) / 365.25 : 0;
  const cagr = (end: number) =>
    years >= 1 && invested > 0 && end > 0 ? ((end / invested) ** (1 / years) - 1) * 100 : null;

  return {
    taxRate,
    timeline: {
      reinvested,
      cashOnly,
      stocksOnly,
      advantage,
      spyShares: spySharesSeries,
    },
    events,
    positions: results,
    summary: {
      firstDate: start,
      lastDate,
      years,
      invested,
      stocksValue,
      dividendsGross,
      dividendsTax,
      dividendsNet,
      spyShares,
      spyValue,
      spyCost,
      spyAvgPrice: spyShares > 0 ? spyCost / spyShares : null,
      spyLastPrice,
      cash,
      totalReinvested,
      totalCashOnly,
      totalStocksOnly: stocksValue,
      advantage: totalReinvested - totalCashOnly,
      advantagePct:
        totalCashOnly > 0 ? ((totalReinvested - totalCashOnly) / totalCashOnly) * 100 : null,
      spyWeight: totalReinvested > 0 ? (spyValue / totalReinvested) * 100 : null,
      cagrReinvested: cagr(totalReinvested),
      cagrCashOnly: cagr(totalCashOnly),
    },
    warnings,
  };
}
